new ResizeObserver(()=>{if(graphPlan){resizeMap();prepareMap();}reserveWorkbench();root.recordMaterial?.invalidate();}).observe(q('.wb-map'));document.fonts?.ready.then(()=>{graphKey='';prepareMap();});document.fonts?.addEventListener('loadingdone',()=>{graphKey='';prepareMap();root.layoutReservation.invalidate();reserveWorkbench();});
function cliDeviceGroup(group,key,open){
 const details=node('details'),summary=node('summary','',group.id.toUpperCase()+' · '+group.rows.length+' records'),body=node('div','wb-cli-rows');details.dataset.disclosureKey=key;details.dataset.lazyCli='true';details.open=open;
 const mount=()=>{if(!body.childElementCount)body.append(rowTable(group.rows));};
 if(open)mount();summary.addEventListener('click',()=>{if(!root.disclosures.wanted(details))mount();},{capture:true});details.addEventListener('toggle',()=>{if(details.open&&root.disclosures.wanted(details))mount();});details.append(summary,body);return details;
}
scope.listen(element,'review-disclosure-layout',event=>{const details=event.detail.element;if(event.detail.phase==='settled'&&details?.dataset.lazyCli&&!root.disclosures.wanted(details))details.querySelector('.wb-cli-rows')?.replaceChildren();});
function restoreBuilder(saved){
 if(!saved)return;input=structuredClone(saved.input);layout=structuredClone(saved.layout);selected=saved.selected;page=saved.page;tab=saved.tab;pane=saved.pane;historical=saved.historical;snapshots=saved.snapshots;authoring=saved.authoring;sites=saved.sites;templates=saved.templates;cam=saved.camera;selection=new Set(saved.selection||[selected.id]);sectionId=saved.sectionId||'';challenge=saved.challenge;challengeEvidence=saved.challengeEvidence||[];challengeHypothesis=saved.challengeHypothesis;cliResult=saved.cliResult;q('.wb-output').textContent=saved.cliTranscript||'';if(cliResult?.command)presentCommand(cliResult.command,domain.parseBuilderCliCommand(cliResult.command),domain.projectBuilderCliState(input),cliResult.output||'');q('.wb-output').textContent=saved.cliTranscript||'';graphKey='';q('.wb-viewport').dataset.pane=pane;selectPage(page,true);
}
function disposeBuilder(){++graphEpoch;cancelTransitions();for(const animation of animations)animation.cancel();animations.clear();}
function reconcileConfiguration(next){
 next.addressing=domain.reconcileBuilderAddressing(next.graph,next.addressing);next.routing=domain.reconcileBuilderRoutingConfig(next.graph,next.addressing,next.routing);next.ipv6=domain.reconcileBuilderIpv6Config(next.graph,next.addressing,next.ipv6);next.linkProfiles=domain.reconcileBuilderLinkProfiles(next.graph,next.linkProfiles);next.services=domain.reconcileBuilderHostedServices(next.graph,next.services||[]);
 const checked=domain.deserializeBuilderScenario(domain.serializeBuilderScenario(domain.createBuilderScenario('My network',next.graph,next.sourceId,next.destinationId,layout,next.addressing,next.routing,undefined,next.ethernet,next.linkProfiles,next.acl,next.nat,next.dhcp,next.ipv6,next.services)));
 return {...next,...checked};
}
function builderAuthoringControls(){
 const details=node('details','wb-author-network');details.append(node('summary','','Add devices and links'));const tools=node('div','rv-toolbar');details.append(tools);
 for(const kind of ['router','endpoint']){const add=node('button','','Add '+kind);add.type='button';add.addEventListener('click',()=>apply(next=>{const id=domain.nextGeneratedNodeId(next.graph,kind);next.graph.nodes.push({id,label:id.toUpperCase(),kind,builtin:false});layout[id]=domain.deterministicNewNodePoint(next.graph.nodes.length-1);return reconcileConfiguration(next);},'DEVICE ADDED'));tools.append(add);}
 const form=node('form','rv-toolbar'),from=node('select','wb-link-from'),to=node('select','wb-link-to');from.setAttribute('aria-label','Link from');to.setAttribute('aria-label','Link to');const cost=node('input');cost.type='number';cost.min='1';cost.max='999';cost.value='10';cost.setAttribute('aria-label','Link metric');const add=node('button','','Add link');add.type='submit';form.append(from,to,cost,add);details.append(form);
 function devices(){for(const select of [from,to]){const prior=select.value;select.replaceChildren(...input.graph.nodes.map(device=>{const option=node('option','',device.label);option.value=device.id;return option;}));if(input.graph.nodes.some(n=>n.id===prior))select.value=prior;}if(to.value===from.value&&to.options.length>1)to.selectedIndex=1;}
 details.addEventListener('toggle',devices);form.addEventListener('submit',event=>{event.preventDefault();apply(next=>{if(from.value===to.value||domain.undirectedLinkExists(next.graph,from.value,to.value))throw Error('Choose two devices without an existing link.');next.graph.links.push({id:domain.nextGeneratedLinkId(next.graph,from.value,to.value),a:from.value,b:to.value,cost:Number(cost.value),failed:false,builtin:false});return reconcileConfiguration(next);},'LINK ADDED');devices();});q('.wb-canvas').append(details);
 const system=node('details','wb-configure-systems');system.append(node('summary','','Edit system configuration'));const editorForm=node('form'),label=node('label','','Configuration'),select=node('select');select.setAttribute('aria-label','Configuration section');for(const [id,text] of [['addressing','IPv4 addressing'],['routing','OSPF, BGP, policy, and provider'],['ipv6','IPv6'],['ethernet','Ethernet and VLANs'],['acl','Access control'],['nat','NAT'],['dhcp','DHCP'],['linkProfiles','Link characteristics'],['services','Hosted services']]){const option=node('option','',text);option.value=id;select.append(option);}label.append(select);const editor=node('textarea');editor.setAttribute('aria-label','System configuration JSON');editor.rows=14;const submit=node('button','','Apply configuration');submit.type='submit';editorForm.append(label,editor,submit);system.append(editorForm);q('.wb-systems').append(system);
 const refresh=()=>{editor.value=JSON.stringify(input[select.value],null,2);};select.addEventListener('change',refresh);system.addEventListener('toggle',()=>{if(system.open)refresh();});editorForm.addEventListener('submit',event=>{event.preventDefault();apply(next=>{next[select.value]=JSON.parse(editor.value);return reconcileConfiguration(next);},'CONFIGURATION UPDATED');});
 const sourceLabel=node('label','','Source'),source=node('select');source.setAttribute('aria-label','Probe source');for(const device of input.graph.nodes){const option=node('option','',device.label);option.value=device.id;source.append(option);}source.value=input.sourceId;source.addEventListener('change',()=>{input.sourceId=source.value;snapshot('PROBE SOURCE SELECTED');});sourceLabel.append(source);q('.wb-secondary-tools .rv-toolbar').append(sourceLabel);
 const trace=node('button','','Run traceroute');trace.type='button';trace.addEventListener('click',()=>runProbe('traceroute'));q('.wb-secondary-tools .rv-toolbar').append(trace);
}
builderAuthoringControls();

